def _copy_item(item: Item) -> Item:
    """Return a standalone copy of *item*, preserving its TOML rendering.

    The returned item is disconnected from the original one (new containers
    and trivia) so it can be freely reassembled, e.g. when reordering keys,
    without modifying the source document.
    """
    if isinstance(item, (Table, InlineTable)):
        value = item.value
        body = [
            (
                copy.deepcopy(k) if k is not None else None,
                _copy_item(v),
            )
            for k, v in value.body
        ]
        return type(item)(value.copy(body=body), item.trivia.copy())
    if isinstance(item, Array):
        return type(item)(
            [_copy_item(v) for v in item.value], item.trivia.copy()
        )
    if isinstance(item, AoT):
        return AoT(
            [_copy_item(table) for table in item],
            item.name,
            item._parsed,
        )
    return copy.deepcopy(item)"}

