def _key_sort_key(pair: tuple) -> tuple[int, Any]:
    """Sort key used to order table entries: keys sorted alphabetically,
    with tables coming last (so that simple items are emitted first, as the
    TOML format requires)."""
    key, value = pair
    key = key.key if isinstance(key, Key) else key
    return (isinstance(value, (Table, AoT, InlineTable)), key)


def _reorder_table(table: Table, sort_keys: bool) -> Table:
    """Return a copy of *table* with its top-level entries sorted by key.

    Nested tables and arrays of tables are reordered recursively.  The
    original table (and its items) is left untouched.
    """
    container = table.value
    body: list[tuple[Key | None, Item]] = []
    for k, v in container.body:
        if k is None:
            body.append((k, _copy_item(v)))
        elif sort_keys and isinstance(v, (Table, AoT)):
            body.append((copy.deepcopy(k), _reorder_table(_copy_item(v), True)))
        else:
            body.append((k, _copy_item(v)))
    entries = [(k, v) for k, v in body if k is not None]
    if sort_keys:
        entries = sorted(entries, key=_key_sort_key)

    new = type(table)(container.copy(), table.trivia.copy())
    for k, v in entries:
        # The new container is empty, so append() always takes the fast
        # _raw_append path.
        new.append(k, v)
    for k, v in body:
        if k is None:
            new._value._raw_append(None, v)
    return new


